import {test as base,expect} from '@playwright/test';

// Every route is generated by test:consumer from installed package tarballs.
// React uses actual Dialog/AlertDialog/Sheet compositions; native uses the
// public controllers and real <dialog> top-layer containing blocks.
const test=base.extend({page:async({page},use,info)=>{
  const errors=[];
  page.on('pageerror',error=>errors.push({kind:'pageerror',message:error.message}));
  page.on('console',message=>{
    if(message.type()==='error'||message.type()==='warning'&&/hydrat|uncaught|invalid hook|cannot update|does not match|did not match/i.test(message.text()))errors.push({kind:`console.${message.type()}`,message:message.text(),location:message.location()});
  });
  await use(page);
  await info.attach('browser-errors.json',{body:JSON.stringify(errors,null,2),contentType:'application/json'});
  // Widgets intentionally loads a missing avatar to exercise its fallback.
  // The fixture also has no favicon; preserve both errors in the evidence.
  const expected404=['/not-an-avatar.png','/favicon.ico'];
  expect(errors.filter(error=>!(error.kind==='console.error'&&error.message.includes('404')&&expected404.some(path=>error.location?.url===`http://127.0.0.1:4173${path}`))),'no unexpected browser errors or hydration warnings').toEqual([]);
}});
const kinds=['react','vanilla'];
const viewports=[{width:1280,height:900},{width:1920,height:1080},{width:390,height:844},{width:320,height:720}];
const clamp=(minimum,preferred,maximum)=>Math.max(minimum,Math.min(preferred,maximum));
const expectedDialog=(width,inset=16)=>Math.min(clamp(384,width*.4,768),width-inset*2);
const expectedConfirm=(width,inset=16)=>Math.min(clamp(320,width*.3,512),width-inset*2);
const expectedSideSheet=width=>Math.min(clamp(384,width*.6,1024),width);
const expectedBlockSheet=height=>Math.min(736,height*.8);
async function settle(page){await page.evaluate(async()=>{await document.fonts.ready;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));});}
async function configure(page,viewport){
  await page.setViewportSize(viewport);await page.emulateMedia({reducedMotion:'reduce',colorScheme:'light'});
  await page.addInitScript(()=>localStorage.setItem('ui.theme.mode','light'));
}
async function box(locator){
  return locator.evaluate(node=>{
    const r=node.getBoundingClientRect(),s=getComputedStyle(node);
    return {tag:node.tagName,className:node.className,side:node.dataset.side,x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom,
      cssWidth:parseFloat(s.width),cssHeight:parseFloat(s.height),minInlineSize:s.minInlineSize,maxInlineSize:s.maxInlineSize,maxBlockSize:s.maxBlockSize,
      clientWidth:node.clientWidth,scrollWidth:node.scrollWidth,clientHeight:node.clientHeight,scrollHeight:node.scrollHeight,
      position:s.position,padding:s.padding,borderWidth:s.borderWidth,boxSizing:s.boxSizing};
  });
}
function expectNear(actual,expected,label){expect(Math.abs(actual-expected),`${label}: expected ${expected} CSS px, received ${actual}`).toBeLessThanOrEqual(.1);}
async function assertWidth(locator,width,viewport,inset=0){
  await expect(locator).toBeVisible();const result=await box(locator);
  expectNear(result.width,width,'border-box width');expectNear(result.cssWidth,width,'computed width');
  expect(result.boxSizing).toBe('border-box');expect(result.x).toBeGreaterThanOrEqual(inset-.1);expect(result.right).toBeLessThanOrEqual(viewport.width-inset+.1);
  expect(result.scrollWidth,'overlay contents must not escape horizontally').toBeLessThanOrEqual(result.clientWidth+1);
  return result;
}
async function assertFooter(overlay,viewport){
  const outer=await box(overlay),footer=await box(overlay.locator(':scope>.xui-dialog-footer'));
  expect(footer.x).toBeGreaterThanOrEqual(outer.x-.1);expect(footer.right).toBeLessThanOrEqual(outer.right+.1);
  expect(footer.y).toBeGreaterThanOrEqual(outer.y-.1);expect(footer.bottom).toBeLessThanOrEqual(Math.min(outer.bottom,viewport.height)+.1);
}
async function capture(page,info,name,expected){
  const actual=await page.evaluate(()=>{
    const root=document.documentElement,s=getComputedStyle(root);
    const names=['--layout-dialog-width-ratio','--layout-dialog-min-width','--layout-dialog-max-width','--layout-dialog-width',
      '--layout-confirm-width-ratio','--layout-confirm-min-width','--layout-confirm-max-width','--layout-confirm-width',
      '--layout-drawer-width-ratio','--layout-drawer-min-width','--layout-drawer-max-width','--layout-drawer-width',
      '--layout-sheet-block-size','--sheet-max-block-size','--layout-viewport-inset','--nav-drawer-max-inline-size'];
    const measure=node=>{const b=node.getBoundingClientRect(),style=getComputedStyle(node);return {tag:node.tagName,className:node.className,side:node.dataset.side,role:node.getAttribute('role'),x:b.x,y:b.y,width:b.width,height:b.height,right:b.right,bottom:b.bottom,computedWidth:style.width,computedHeight:style.height,maxInlineSize:style.maxInlineSize,clientWidth:node.clientWidth,scrollWidth:node.scrollWidth,clientHeight:node.clientHeight,scrollHeight:node.scrollHeight};};
    return {viewport:{width:innerWidth,height:innerHeight,devicePixelRatio,visualViewportScale:visualViewport.scale},rootFontSize:s.fontSize,documentWidth:root.scrollWidth,
      tokens:Object.fromEntries(names.map(name=>[name,s.getPropertyValue(name).trim()])),
      elements:[...document.querySelectorAll('.xui-dialog,.xui-native-dialog,.xui-dialog-body,.xui-dialog-footer,.xui-shell-sidebar,.xui-nav-item')].filter(node=>node.getClientRects().length).map(measure)};
  });
  await info.attach(`${name}-css-pixels.json`,{body:JSON.stringify({expected,actual},null,2),contentType:'application/json'});
  const path=info.outputPath(`${name}.png`);await page.screenshot({path,animations:'disabled'});await info.attach(`${name}.png`,{path,contentType:'image/png'});
}
async function setRoot(page,name,value){await page.evaluate(({name,value})=>{if(value===null)document.documentElement.style.removeProperty(name);else document.documentElement.style.setProperty(name,value);},{name,value});await settle(page);}
async function openSheet(page,kind,side){
  await page.goto(`/capabilities-${kind}/?sheetSide=${side}`);await expect(page.getByRole('heading',{name:'公共能力',exact:true})).toBeVisible();
  await page.getByRole('button',{name:'打开侧栏',exact:true}).click();
  const sheet=page.getByRole('dialog',{name:'编辑侧栏',exact:true});await expect(sheet).toBeVisible();await settle(page);return sheet;
}
async function closeSheet(page,sheet){await sheet.getByRole('textbox',{name:'草稿',exact:true}).fill('');await sheet.getByRole('button',{name:'关闭侧栏',exact:true}).click();await expect(sheet).toBeHidden();}

for(const kind of kinds){
  for(const viewport of viewports){
    test(`${kind} responsive Dialog, Confirm and lateral Sheets at ${viewport.width}px`,async({page},info)=>{
      test.setTimeout(60000);await configure(page,viewport);
      await page.goto(`/widgets-${kind}/`);await expect(page.getByRole('heading',{name:'公共控件',exact:true})).toBeVisible();
      const trigger=page.getByRole('button',{name:'嵌套选择',exact:true});await trigger.click();
      const dialog=page.getByRole('dialog',{name:'选择确认',exact:true});await settle(page);
      const defaultWidth=expectedDialog(viewport.width);
      const ordinary=await assertWidth(dialog,defaultWidth,viewport,16);await assertFooter(dialog,viewport);
      if(kind==='vanilla')expect(ordinary.tag).toBe('DIALOG');
      expectNear(ordinary.x,(viewport.width-defaultWidth)/2,'centered ordinary dialog');
      // Intentional new defaults: at 1920px Dialog becomes 768px (was 512px).
      // The 1280px value remains 512px; narrow viewports retain both insets.
      await capture(page,info,'ordinary-default',{width:defaultWidth,previousFixedWidth:512});
      await setRoot(page,'--layout-viewport-inset','24px');
      await assertWidth(dialog,expectedDialog(viewport.width,24),viewport,24);
      await capture(page,info,'ordinary-inset-override',{width:expectedDialog(viewport.width,24),inset:24});
      await setRoot(page,'--layout-viewport-inset',null);await assertWidth(dialog,defaultWidth,viewport,16);
      if(viewport.width>=1280){
        // 1920×40% lands exactly on the 48rem cap. Increasing the public
        // preference proves that the cap is real rather than a coincidence.
        await setRoot(page,'--layout-dialog-width-ratio','90%');await assertWidth(dialog,768,viewport,16);
        await capture(page,info,'ordinary-upper-bound',{width:768,preferredRatio:'90%',maximum:'48rem'});
        await setRoot(page,'--layout-dialog-width-ratio',null);await assertWidth(dialog,defaultWidth,viewport,16);
      }
      await dialog.getByRole('button',{name:'取消选择',exact:true}).focus();await page.keyboard.press('Escape');await expect(dialog).toBeHidden();await expect(trigger).toBeFocused();

      for(const side of ['end','start']){
        const sheet=await openSheet(page,kind,side),sheetWidth=expectedSideSheet(viewport.width);
        await expect(sheet).toHaveAttribute('data-side',side);
        const lateral=await assertWidth(sheet,sheetWidth,viewport);
        expectNear(lateral.height,viewport.height,'lateral sheet height');expectNear(lateral.y,0,'lateral sheet top');
        expectNear(side==='start'?lateral.x:lateral.right,side==='start'?0:viewport.width,`${side} sheet edge`);
        await assertFooter(sheet,viewport);
        // Intentional defaults: lateral Sheet widths are 768/1024/384/320px
        // at 1280/1920/390/320px, replacing the previous fixed 46rem cap.
        await capture(page,info,`sheet-${side}`,{width:sheetWidth,height:viewport.height,previousFixedWidth:736});
        if(side==='end'){
          await sheet.getByRole('button',{name:'关闭侧栏',exact:true}).click();
          const confirm=page.getByRole('alertdialog');await expect(confirm).toBeVisible();await settle(page);
          const confirmWidth=expectedConfirm(viewport.width),confirmation=await assertWidth(confirm,confirmWidth,viewport,16);
          if(kind==='vanilla')expect(confirmation.tag).toBe('DIALOG');
          expectNear(confirmation.x,(viewport.width-confirmWidth)/2,'nested confirmation uses the viewport containing block');
          await assertFooter(confirm,viewport);await expect(confirm.getByRole('button',{name:'继续编辑',exact:true})).toBeFocused();
          // Confirm now becomes 512px at 1920px and 320px at 390px. Its
          // 1280px width is still 384px; at 320px the viewport cap wins.
          await capture(page,info,'nested-confirm-default',{width:confirmWidth,previousFixedWidth:384});
          await setRoot(page,'--layout-viewport-inset','24px');await assertWidth(confirm,expectedConfirm(viewport.width,24),viewport,24);
          await setRoot(page,'--layout-viewport-inset',null);await assertWidth(confirm,confirmWidth,viewport,16);
          await page.keyboard.press('Escape');await expect(confirm).toBeHidden();await expect(sheet).toBeVisible();await expect(sheet.getByRole('textbox',{name:'草稿',exact:true})).toHaveValue('保留草稿');
        }
        await closeSheet(page,sheet);
      }
    });

    for(const side of ['top','bottom']){
      test(`${kind} ${side} Sheet block size stays independent of responsive width at ${viewport.width}px`,async({page},info)=>{
        await configure(page,viewport);const sheet=await openSheet(page,kind,side);await expect(sheet).toHaveAttribute('data-side',side);
        const expectedHeight=expectedBlockSheet(viewport.height),initial=await assertWidth(sheet,viewport.width,viewport);
        expectNear(initial.height,expectedHeight,'top/bottom sheet height');expectNear(initial.cssHeight,expectedHeight,'computed top/bottom block size');
        expectNear(side==='top'?initial.y:initial.bottom,side==='top'?0:viewport.height,`${side} sheet edge`);await assertFooter(sheet,viewport);
        const body=sheet.locator(':scope>.xui-dialog-body');expect(await body.evaluate(node=>node.scrollHeight>node.clientHeight),'long content must scroll inside the sheet').toBe(true);
        await body.evaluate(node=>{node.scrollTop=node.scrollHeight;});await assertFooter(sheet,viewport);
        // Vertical defaults intentionally remain min(46rem,80dvh), including
        // 736px at 1920×1080. The new 60% inline preference is never a height.
        await capture(page,info,`${side}-default`,{width:viewport.width,height:expectedHeight,blockSize:'46rem',maxBlockSize:'80dvh'});
        await setRoot(page,'--layout-drawer-width','20vw');
        const widthOnly=await assertWidth(sheet,viewport.width,viewport);expectNear(widthOnly.height,expectedHeight,'inline override must not affect block size');
        await setRoot(page,'--layout-sheet-block-size','20rem');const shorter=await assertWidth(sheet,viewport.width,viewport);
        expectNear(shorter.height,320,'independent block size override');await assertFooter(sheet,viewport);
        await capture(page,info,`${side}-independent-block-override`,{width:viewport.width,height:320,inlineOverride:'20vw',blockOverride:'20rem'});
        await setRoot(page,'--layout-drawer-width',null);await setRoot(page,'--layout-sheet-block-size',null);
        expectNear((await box(sheet)).height,expectedHeight,'restored vertical sheet height');await closeSheet(page,sheet);
      });
    }
  }

  test(`${kind} responsive overlays preserve 216/60px navigation and the separate 288px drawer cap`,async({page},info)=>{
    test.setTimeout(60000);await configure(page,viewports[0]);
    for(const viewport of viewports){
      await page.setViewportSize(viewport);await page.goto(`/layout-typography-${kind}/`);await page.waitForFunction(()=>!!window.layoutTypography);await settle(page);
      if(viewport.width>=768){
        const sidebar=page.locator('.xui-shell-sidebar');expectNear((await box(sidebar)).width,216,'expanded navigation rail');
        await capture(page,info,`nav-${viewport.width}-expanded`,{sidebarWidth:216});
        await page.getByRole('button',{name:'紧凑导航',exact:true}).click();await settle(page);expectNear((await box(sidebar)).width,60,'compact navigation rail');
        await capture(page,info,`nav-${viewport.width}-compact`,{sidebarWidth:60});
      }else{
        const trigger=page.getByRole('button',{name:'工作导航',exact:true});await trigger.click();const drawer=page.getByRole('dialog');
        const actual=await assertWidth(drawer,288,viewport,16);expectNear(actual.x,16,'navigation drawer start inset');
        expect(actual.maxInlineSize).toBe('288px');await capture(page,info,`nav-${viewport.width}-drawer`,{width:288,maxInlineSize:288,inset:16});
        await page.keyboard.press('Escape');await expect(drawer).toBeHidden();await expect(trigger).toBeFocused();
      }
      expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(viewport.width+1);
    }
  });

  test(`${kind} invalid fixture sheetSide falls back to the real end-side API`,async({page},info)=>{
    const viewport=viewports[0];await configure(page,viewport);const sheet=await openSheet(page,kind,'diagonal');await expect(sheet).toHaveAttribute('data-side','end');
    const actual=await assertWidth(sheet,expectedSideSheet(viewport.width),viewport);expectNear(actual.right,viewport.width,'invalid side fallback edge');
    await capture(page,info,'invalid-side-fallback',{side:'end',width:expectedSideSheet(viewport.width)});await closeSheet(page,sheet);
  });
}
